return {
  json: {
    error: {
      code: "INVALID_INPUT",
      message: "account_id must be a non-empty string; product_id must be null or a non-empty string"
    }
  }
};

const rows = $input.all().map(item => item.json);

const input = $('When Executed by Another Workflow').first().json;

const accountId = input.account_id.trim();
const productId = input.product_id == null
  ? null
  : input.product_id.trim();

const accountFound = rows.some(
  row => row.account_id === accountId
);

// Account does not exist
if (!accountFound) {
  return [{
    json: {
      account_id: accountId,
      product_id: productId,
      found: false,
      orders: []
    }
  }];
}

// PostgreSQL DATE -> YYYY-MM-DD
const toDate = value =>
  value == null ? null : String(value).slice(0, 10);

// Group order lines by order_id
const orderMap = new Map();

for (const row of rows) {
  // Existing account with no matching purchase
  if (!row.order_id) continue;

  if (!orderMap.has(row.order_id)) {
    orderMap.set(row.order_id, {
      order_id: row.order_id,
      order_date: toDate(row.order_date),
      order_status: row.order_status,
      lines: []
    });
  }

  // Preserve individual transaction line identity
  if (row.order_line_id) {
    orderMap.get(row.order_id).lines.push({
      order_line_id: row.order_line_id,
      product_id: row.product_id,
      sku: row.sku,
      product_name: row.product_name,
      quantity: row.quantity,
      unit_price_idr: row.unit_price_idr,
      installation_location: row.installation_location
    });
  }
}

return [{
  json: {
    account_id: accountId,
    product_id: productId,
    found: true,
    orders: Array.from(orderMap.values())
  }
}];
